        phone = _norm_phone(f.get("telephone"))
        addr = _norm_addr(f.get("address"))
    else:
        first = last = ""
        dob = None
        ssn = email = phone = addr = ""
    return {
        "id": rec["id"],
        "source": src,
        "first": first,
        "last": last,
        "dob": dob,
        "ssn": ssn,
        "email": email,
        "phone": phone,
        "addr": addr,
    }


def _edit1(s):
    if not s:
        return set()
    out = set()
    for i in range(len(s) + 1):
        for c in "abcdefghijklmnopqrstuvwxyz0123456789.@_-":
            out.add(s[:i] + c + s[i:])
    for i in range(len(s)):
        out.add(s[:i] + s[i + 1:])
    for i in range(len(s)):
        for c in "abcdefghijklmnopqrstuvwxyz0123456789.@_-":
            out.add(s[:i] + c + s[i + 1:])
    return out


def _email_key(e):
    if not e:
        return None
    if "@" in e:
        local, domain = e.split("@", 1)
    else:
        local, domain = e, ""
    return (local, domain)


