    if len(la) > len(lb):
        la, lb = lb, la
    i = j = 0
    skipped = False
    while i < len(la) and j < len(lb):
        if la[i] == lb[j]:
            i += 1
            j += 1
        else:
            if skipped:
                return False
            skipped = True
            j += 1
    return True


