    if len(la) == len(lb):
        diffs = sum(1 for x, y in zip(la, lb) if x != y)
        return diffs <= 1
    # insertion/deletion
    if len(la) > len(lb):
        la, lb = lb, la
    i = j = 0
    skipped = False
    while i < len(la) and j < len(lb):
