        return set()
    out = set()
    alphabet = "abcdefghijklmnopqrstuvwxyz0123456789.@_-"
    for i in range(len(s) + 1):
        for c in alphabet:
            out.add(s[:i] + c + s[i:])
    for i in range(len(s)):
        out.add(s[:i] + s[i + 1:])
    for i in range(len(s)):
        for c in alphabet:
            out.add(s[:i] + c + s[i + 1:])
    return out


def _email_key(e):
