def _email_key(e):
    if "@" in e:
        local, domain = e.split("@", 1)
    else:
        local, domain = e, ""
    return (local, domain)


def _email_similar(a, b):
    if not a or not b:
        return False
    if a == b:
        return True
    la, da = _email_key(a)
    lb, db = _email_key(b)
    if da != db:
        return False
    if abs(len(la) - len(lb)) > 1:
        return False
    if len(la) == len(lb):
        diffs = sum(1 for x, y in zip(la, lb) if x != y)
        return diffs <= 1
    if len(la) > len(lb):
        la, lb = lb, la
    i = j = 0
    skipped = False
    while i < len(la) and j < len(lb):
        if la[i] == lb[j]:
            i += 1
            j += 1
        else:
            if skipped:
                return False
            skipped = True
            j += 1
    return True


def _name_compatible(a_first, a_last, b_first, b_last, ambiguous):
    af = _norm_name(a_first)
    bf = _norm_name(b_first)
    al = _norm_name(a_last)
    bl = _norm_name(b_last)
    if al and bl and al != bl:
        return False
    if not af or not bf:
        return True
    if af == bf:
        return True
    if af in ambiguous or bf in ambiguous:
        return True
    return False


