    return {
        "id": rec["id"],
        "source": src,
        "first": first,
        "last": last,
        "dob": dob,
        "ssn": ssn,
        "email": email,
        "phone": phone,
        "addr": addr,
    }


def _edit1(s):
    if not s:
        return set()
    out = set()
    alphabet = "abcdefghijklmnopqrstuvwxyz0123456789.@_-"
    for i in range(len(s) + 1):
        for c in alphabet:
            out.add(s[:i] + c + s[i:])
    for i in range(len(s)):
        out.add(s[:i] + s[i + 1:])
    for i in range(len(s)):
        for c in alphabet:
            out.add(s[:i] + c + s[i + 1:])
    return out


def _email_key(e):
    if "@" in e:
        local, domain = e.split("@", 1)
    else:
        local, domain = e, ""
    return (local, domain)


def _email_similar(a, b):
    if not a or not b:
        return False
    if a == b:
        return True
    la, da = _email_key(a)
    lb, db = _email_key(b)
    if da != db:
        return False
    if abs(len(la) - len(lb)) > 1:
        return False
    if len(la) == len(lb):
        diffs = sum(1 for x, y in zip(la, lb) if x != y)
        return diffs <= 1
    if len(la) > len(lb):
        la, lb = lb, la
    i = j = 0
    skipped = False
    while i < len(la) and j < len(lb):
        if la[i] == lb[j]:
            i += 1
            j += 1
        else:
            if skipped:
                return False
            skipped = True
            j += 1
    return True


